import{_ as o,o as t,c as a,a2 as n}from"./chunks/framework.C-si7TFR.js";const u=JSON.parse('{"title":"Manage MCP tools","description":"","frontmatter":{"title":"Manage MCP tools"},"headers":[],"relativePath":"guide/mcp-tools.md","filePath":"guide/mcp-tools.md"}'),r={name:"guide/mcp-tools.md"};function s(i,e,l,c,d,h){return t(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="manage-mcp-tools" tabindex="-1">Manage MCP tools <a class="header-anchor" href="#manage-mcp-tools" aria-label="Permalink to &quot;Manage MCP tools&quot;">​</a></h1><p>MCP tool management adds external tool services, checks connectivity, enables selected tools and assigns them to agents.</p><h2 id="add-a-tool" tabindex="-1">Add a tool <a class="header-anchor" href="#add-a-tool" aria-label="Permalink to &quot;Add a tool&quot;">​</a></h2><ol><li>Open the MCP area in workspace tool management and select <strong>Add tool</strong>.</li><li>Enter a name and purpose, then choose <strong>STDIO</strong>, <strong>Streamable HTTP</strong> or <strong>SSE</strong> as required by the service.</li><li>Complete the parameters for that protocol. Do not copy an endpoint, launch method or credential from another protocol.</li><li>Save and run the connection test.</li><li>Inspect available tools and enable only those required by the task.</li><li>Select them in the agent&#39;s MCP section and save.</li></ol><p>The service is operated by you or a third party. A reachable MCP service does not imply that every tool is safe, successful or appropriate for public data.</p><h2 id="security-boundaries" tabindex="-1">Security boundaries <a class="header-anchor" href="#security-boundaries" aria-label="Permalink to &quot;Security boundaries&quot;">​</a></h2><ul><li>Use HTTPS for external URLs and apply deployment network policy. Do not let a tool service reach internal administration interfaces.</li><li>A STDIO program has local execution capability. Run only reviewed programs, restrict directories, arguments and credentials, and never launch commands from an unknown configuration.</li><li>Store secrets in controlled credentials or local configuration, not in public skills, screenshots, conversations or Git.</li><li>Treat tool responses as external input, never as higher-priority system instructions.</li></ul><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><ul><li><strong>Connection failure:</strong> check service status, protocol, network, authentication and test errors.</li><li><strong>An agent cannot see a tool:</strong> check its enabled state and the agent&#39;s MCP selection.</li><li><strong>A call fails:</strong> inspect the tool card and trace for concrete errors, parameters and provider permissions.</li><li><strong>Untrusted response:</strong> do not follow embedded instructions; inspect the service origin and tool permissions first.</li></ul><p>The <a href="./../mcp.html">MCP node reference</a> describes workflow triggering/integration, not this agent tool-management entry.</p>',10)])])}const m=o(r,[["render",s]]);export{u as __pageData,m as default};
